package com.companion.growth;
import com.companion.ai.growth.*; import com.companion.dto.response.CharacterResponse; import com.companion.entity.CharacterGrowth; import com.companion.mapper.CharacterGrowthMapper; import com.companion.service.CharacterService; import com.companion.service.impl.CharacterGrowthServiceImpl; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class CharacterGrowthConcurrencyTest {
 @Test void staleCasRetriesOnceAndCanWin(){var m=mock(CharacterGrowthMapper.class);var c=mock(CharacterService.class);var e=mock(LlmGrowthEvaluator.class);when(c.get(1L,2L)).thenReturn(ai());when(m.selectOne(any())).thenReturn(growth(0,"old"),growth(1,"newer"));when(e.evaluate(any(),any())).thenReturn(change("first"),change("retry"));when(m.updateIfVersionMatches(any(),eq(0))).thenReturn(0);when(m.updateIfVersionMatches(any(),eq(1))).thenReturn(1);var result=new CharacterGrowthServiceImpl(m,c,e).evaluateAndUpdate(1L,2L,context());assertThat(result.getGrowthSummary()).isEqualTo("retry");verify(e,times(2)).evaluate(any(),any());}
 @Test void secondConflictPreservesLatestAndStops(){var m=mock(CharacterGrowthMapper.class);var c=mock(CharacterService.class);var e=mock(LlmGrowthEvaluator.class);when(c.get(anyLong(),anyLong())).thenReturn(ai());when(m.selectOne(any())).thenReturn(growth(0,"old"),growth(1,"latest"));when(e.evaluate(any(),any())).thenReturn(change("x"));when(m.updateIfVersionMatches(any(),anyInt())).thenReturn(0);var result=new CharacterGrowthServiceImpl(m,c,e).evaluateAndUpdate(1L,2L,context());assertThat(result.getGrowthSummary()).isEqualTo("latest");verify(m,times(2)).updateIfVersionMatches(any(),anyInt());verify(e,times(2)).evaluate(any(),any());}
 @Test void unchangedNeverUpdates(){var m=mock(CharacterGrowthMapper.class);var c=mock(CharacterService.class);var e=mock(LlmGrowthEvaluator.class);when(c.get(anyLong(),anyLong())).thenReturn(ai());when(m.selectOne(any())).thenReturn(growth(0,"old"));when(e.evaluate(any(),any())).thenReturn(GrowthEvaluation.unchanged());new CharacterGrowthServiceImpl(m,c,e).evaluateAndUpdate(1L,2L,context());verify(m,never()).updateIfVersionMatches(any(),anyInt());}
 private GrowthEvaluationContext context(){return new GrowthEvaluationContext("identity","relationship","memory","meaningful","reply");} private GrowthEvaluation change(String s){return new GrowthEvaluation(true,s,"adapt","understand","direction");} private CharacterGrowth growth(int v,String s){var g=new CharacterGrowth();g.setId(3L);g.setVersion(v);g.setGrowthSummary(s);g.setBehaviorAdaptation("a");g.setUserUnderstanding("u");g.setGrowthDirection("d");return g;} private CharacterResponse ai(){var c=new CharacterResponse();c.setCharacterType("AI");return c;}
}
